const $=s=>document.querySelector(s);const fmt=n=>n.toLocaleString('fr-BE',{maximumFractionDigits:2});
const gifts=[{n:8,title:'La première pause gourmande',text:'Un coffret à ouvrir ensemble, pour savourer les premiers pas du parcours.',img:'coffret.png'},{n:19,title:'Le goût du partage',text:'Une sélection gourmande Rouge Clémence, pour prendre le temps de se retrouver.',img:'partage.png'},{n:30,title:'Une parenthèse bien méritée',text:'Une attention artisanale à composer selon les envies de l’équipe.',img:'ambiance.png'},{n:42,title:'Les beaux souvenirs',text:'Une dernière attention pour célébrer le chemin parcouru ensemble.',img:'coffret.png'}];
const metrics=[['Échéances internes respectées',95,35,92,'%'],['Dossiers complets à première revue',98,30,96,'%'],['Demandes traitées dans le délai annoncé',90,20,88,'%'],['Actions d’amélioration réalisées',2,15,2,'actions']];
const initial=()=>({position:16.4,month:5,lastScore:92,lastGain:3.68,message:'Chaque dossier bien préparé, chaque information transmise et chaque coup de main font avancer notre équipe. Merci pour votre attention au quotidien.',project:[true,true,true,false,false],history:[],values:metrics.map(x=>x[3]),quality:true});
let state;try{state=JSON.parse(localStorage.getItem('rc-lexekho-v1'))||initial()}catch{state=initial()}let page='parcours';
const save=()=>{try{localStorage.setItem('rc-lexekho-v1',JSON.stringify(state))}catch{}};const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function gift(g){const unlocked=state.position>=g.n;modal(`<span class="badge">ATTENTION · CASE ${g.n}</span><h2 style="margin-top:12px">${g.title}</h2><img src="assets/${g.img}" alt="Coffret de l’univers Rouge Clémence"><p>${g.text}</p><span class="tag ${unlocked?'':'locked'}">${unlocked?'Palier acquis':'Encore '+fmt(g.n-state.position)+' cases'}</span><p class="small muted" style="margin-top:20px">Proposition de démonstration. Composition, budget et livraison à convenir avec Rouge Clémence. Aucun cadeau n’est commandé depuis cette maquette.</p>`)}
function board(){let coords=[];for(let i=0;i<48;i++){let row=Math.floor(i/12),col=i%12;coords.push([45+(row%2?11-col:col)*47,75+row*99])}let d=coords.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');let current=Math.floor(state.position);let [x,y]=current?coords[Math.min(47,current-1)]:[23,75];return `<svg viewBox="0 0 610 425" role="group" aria-label="Parcours de 48 cases. Position actuelle ${fmt(state.position)}."><path d="${d}" fill="none" stroke="#e7e6d9" stroke-width="13" stroke-linejoin="round"/><path d="${coords.slice(0,current).map((p,i)=>(i?'L':'M')+p.join(',')).join(' ')}" fill="none" stroke="#aeb89c" stroke-width="8" stroke-linejoin="round"/>${['01 · PRENDRE SON ÉLAN','02 · CULTIVER LE LIEN','03 · GRANDIR ENSEMBLE','04 · CÉLÉBRER LE CHEMIN'].map((t,i)=>`<text x="35" y="${35+i*99}" fill="#7e8771" font-size="10" letter-spacing="1.3">${t}</text>`).join('')}${coords.map(([x,y],i)=>{let g=gifts.find(g=>g.n===i+1);return `<g class="node" role="button" tabindex="0" aria-label="Case ${i+1}${g?' : '+g.title:''}" data-case="${i+1}"><circle cx="${x}" cy="${y}" r="${g?19:14}" fill="${g?'#782f43':i<current?'#637956':'#fffdf7'}" stroke="${g?'#782f43':i<current?'#637956':'#dcded1'}"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="${g||i<current?'white':'#858a7d'}" font-size="${g?13:10}">${g?'♧':i+1}</text>${g?`<text x="${x}" y="${y+33}" text-anchor="middle" font-size="9" fill="#782f43">CASE ${i+1}</text>`:''}</g>`}).join('')}<g class="pawn" transform="translate(${x},${y-29})"><circle r="14" fill="#e2b65e" stroke="white" stroke-width="3"/><text y="4" text-anchor="middle" font-size="10" font-weight="bold" fill="#4c4636">L</text></g></svg>`}
const intro=(eyebrow,title,sub)=>`<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${sub}</p></div><span class="pill">● Équipe Lex EKho</span></div>`;
function parcours(){let next=gifts.find(g=>g.n>state.position);let goal=state.project.filter(Boolean).length*20;return intro('ENSEMBLE, CHAQUE ÉTAPE COMPTE','Les attentions se <em>cultivent.</em>','Un peu de progrès. Beaucoup de collectif. Et de belles occasions de se retrouver.')+`<div class="layout"><div><section class="card boardcard"><div class="board-head"><div><span class="eyebrow">NOTRE AVENTURE · 12 MOIS</span><h2 style="margin-top:8px">Le chemin que l’on fait ensemble</h2></div><span class="legend"><b>${fmt(state.position)}</b> / 48 cases<br>Mois ${state.month} sur 12</span></div><div class="board">${board()}</div><div class="board-foot"><span><span class="dot">●</span> Notre équipe &nbsp; <span style="color:#b18c3e">●</span> Vous êtes ici</span><span>♧ 4 attentions à découvrir · Cliquez sur une case</span></div></section><div class="lower"><section class="card note"><span class="badge">LE MOT DE L’ÉQUIPE · EXEMPLE</span><p>« ${escape(state.message)} »</p><small class="muted">Un message proposé pour la direction</small></section><section class="card"><span class="eyebrow">LE DERNIER PAS</span><div class="row"><h3>Mois ${state.month}</h3><span class="score">+${fmt(state.lastGain)}</span></div><p class="muted small">cases gagnées · Score collectif : ${fmt(state.lastScore)} %</p><button class="button secondary wide" id="how">Comprendre notre progression ↗</button></section></div></div><div class="right"><section class="card next"><img src="assets/${(next||gifts[3]).img}" alt="Coffret Rouge Clémence"><div><span class="badge">${next?'LA PROCHAINE ATTENTION · CASE '+next.n:'LES QUATRE PALIERS SONT ACQUIS'}</span><h3>${next?next.title:'Un beau chemin accompli'}</h3><p>${next?'Encore '+fmt(next.n-state.position)+' cases avant ce prochain moment à partager.':'Les petites attentions ont accompagné toute votre année.'}</p><button class="button wide" id="discover">Découvrir l’attention ↗</button></div></section><section class="card goal"><span class="eyebrow">NOTRE AMBITION COMMUNE</span><h3>Mieux transmettre,<br>mieux travailler ensemble.</h3><div class="row"><span class="number">${goal} %</span><span class="small">${goal/20} / 5 étapes</span></div><div class="bar"><i style="width:${goal}%"></i></div><small>Créer notre guide d’accueil et de transmission. Un projet distinct du parcours mensuel.</small><p class="small" style="margin-top:12px">${goal===100?'✦ Projet accompli : célébration collective acquise.':'À 100 % : un moment collectif pour toute l’équipe.'}</p><button class="button secondary wide" id="project">Voir le projet commun</button></section></div></div>`}
function attentions(){return intro('LES MOMENTS QUI COMPTENT','Un merci, <em>qui se partage.</em>','Quatre attentions de parcours, acquises une seule fois dès le franchissement du palier.')+`<div class="cards">${gifts.map((g,i)=>`<article class="card gift"><img src="assets/${g.img}" alt="Sélection visuelle Rouge Clémence"><div class="row" style="margin-top:15px"><span class="badge">ATTENTION 0${i+1} · CASE ${g.n}</span><span class="tag ${state.position>=g.n?'':'locked'}">${state.position>=g.n?'Palier acquis':'À découvrir'}</span></div><h3>${g.title}</h3><p class="muted">${g.text}</p><button class="button secondary" data-gift="${i}">Voir cette attention ↗</button></article>`).join('')}</div><p class="small muted">Visuels d’ambiance issus de Rouge Clémence. Les compositions et les remises ne sont pas confirmées.</p>`}
const scenes=['Le premier pas','Les petites victoires','Le goût du collectif','Prendre soin du lien','Partager les savoir-faire','Une pause ensemble','Les idées qui grandissent','Le plaisir de transmettre','Un nouveau regard','Les gestes qui comptent','Merci à toute l’équipe','Célébrer notre année'];
function calendrier(){return intro('12 RENDEZ-VOUS, UNE HISTOIRE COMMUNE','L’année des <em>petites attentions.</em>','Les mois sont relatifs au lancement. Les rendez-vous de calendrier restent indépendants des scores.')+`<div class="months">${scenes.map((s,i)=>`<article class="card month ${(i===5||i===10)?'special':''}"><div class="row"><span class="monthnum">${String(i+1).padStart(2,'0')}</span>${i+1===state.month?'<span class="tag">Nous y sommes</span>':''}</div><h3>${s}</h3><p class="small muted">${i===5?'Pause conviviale · attention de calendrier, sans condition de résultat.':i===10?'Un merci de saison · attention de calendrier, sans condition de résultat.':i===11?'Bilan, remerciements et point sur notre projet commun.':'Révélation mensuelle et message à l’équipe.'}</p></article>`).join('')}</div>`}
function score(){return metrics.reduce((s,m,i)=>s+Math.min(1,Math.max(0,state.values[i])/m[1])*m[2],0)}
function direction(){let s=score();return intro('ATELIER DE DÉMONSTRATION','Faire avancer <em>le collectif.</em>','Simulez le prochain mois : saisissez, vérifiez, puis révélez la progression de l’équipe.')+`<section class="card"><div class="row"><div><span class="eyebrow">MOIS ${Math.min(12,state.month+1)} · INDICATEURS FICTIFS</span><h3>Les objectifs de notre équipe</h3></div><span class="tag">Agrégats uniquement</span></div><p class="small muted">Exemples adaptés au dossier fourni : aucun nom, client, montant recouvré ni dossier réel. Cibles et poids fixes pour cette simulation.</p><div class="tablewrap"><table class="metrics"><thead><tr><th>Indicateur</th><th>Cible</th><th>Poids</th><th>Réalisé</th></tr></thead><tbody>${metrics.map((m,i)=>`<tr><td>${m[0]}</td><td>${m[1]} ${m[4]}</td><td>${m[2]} %</td><td><input aria-label="Réalisé : ${m[0]}" type="number" min="0" ${i<3?'max="100"':''} step="${i<3?'0.1':'1'}" value="${state.values[i]}" data-metric="${i}"></td></tr>`).join('')}</tbody></table></div><div class="row"><div><span class="small muted">Score pondéré prévisionnel</span><div class="score" id="calc">${fmt(s)} % → +${fmt(s*.04)} cases</div></div></div><p class="small muted">Atteinte = min(100 %, réalisé ÷ cible × 100). Score = somme des atteintes × poids. Progression = 4 × score ÷ 100. Les fractions se cumulent ; on ne recule jamais.</p><label for="message">Le message qui accompagne cette étape</label><textarea id="message" class="form-message" maxlength="600">${escape(state.message)}</textarea><label class="check"><input type="checkbox" id="quality" ${state.quality?'checked':''}> Contrôle humain effectué : données vérifiées et attentions validables.</label><p class="small muted">Si le contrôle reste ouvert, la publication attend une décision humaine ; aucune sanction automatique.</p><div class="controls"><button class="button" id="publish" ${state.month>=12?'disabled':''}>${state.month>=12?'Année terminée':'Révéler le mois '+(state.month+1)+' à l’équipe →'}</button><span class="small muted">Simulation locale · aucun envoi réel</span></div></section><div class="lower"><section class="card"><h3>Le projet commun</h3><p class="small muted">Guide d’accueil et de transmission : 5 étapes de même poids (20 % chacune). Indépendant du score mensuel.</p><div class="checklist">${['Identifier les besoins','Rédiger les procédures','Préparer les outils','Tester avec l’équipe','Valider et partager le guide'].map((x,i)=>`<label><input type="checkbox" data-project="${i}" ${state.project[i]?'checked':''}> ${x}</label>`).join('')}</div></section><section class="card"><h3>Journal de la simulation</h3><p class="small muted">L’état est conservé dans ce navigateur. Le bouton « Recommencer » restaure l’exemple.</p><ul class="audit">${state.history.length?state.history.map(h=>`<li>${escape(h)}</li>`).join(''):'<li>Situation initiale fictive : mois 5, position 16,4.</li>'}</ul></section></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});$('#main').innerHTML=({parcours,attentions,calendrier,direction}[page])()+`<footer>Maquette conçue à partir de « RC_Dossier_2026 », version du 23 octobre 2026. Personnalisation Lex EKho illustrative, sans données réelles.<br>Visuels : <a href="https://rougeclemence.be" target="_blank" rel="noopener">Rouge Clémence</a> · Conception ludique : <a href="https://leludificateur.be" target="_blank" rel="noopener">Le Ludificateur</a> · Nom du cabinet : <a href="https://lex-ekho.be" target="_blank" rel="noopener">Lex EKho</a>.</footer>`;
 document.querySelectorAll('[data-gift]').forEach(b=>b.onclick=()=>gift(gifts[+b.dataset.gift]));document.querySelectorAll('[data-case]').forEach(b=>{const act=()=>{let n=+b.dataset.case,g=gifts.find(g=>g.n===n);if(g)gift(g);else modal(`<span class="eyebrow">NOTRE PARCOURS · CASE ${n}</span><h2 style="margin-top:14px">${n<=state.position?'Un pas déjà accompli.':'Une nouvelle étape nous attend.'}</h2><p>Chaque progrès d’équipe compte. Cette case accompagne le chemin commun ; elle n’ajoute ni bonus ni points au score.</p><span class="tag">${n<=state.position?'Étape atteinte':'À venir'}</span>`)};b.onclick=act;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act()}}});
 if($('#discover'))$('#discover').onclick=()=>gift(gifts.find(g=>g.n>state.position)||gifts[3]);if($('#how'))$('#how').onclick=()=>modal('<span class="eyebrow">UNE PROGRESSION TRANSPARENTE</span><h2 style="margin-top:14px">Chaque mois, jusqu’à 4 cases.</h2><p>Quatre indicateurs collectifs sont comparés aux cibles définies. Leurs atteintes, plafonnées à 100 %, sont pondérées pour former le score.</p><p><b>Un score de 90 % = 3,6 cases.</b> Les fractions sont conservées. Aucun recul, aucun classement individuel.</p><p>Les paliers 8, 19, 30 et 42 sont acquis au franchissement. Les rendez-vous de calendrier et le projet commun suivent leurs propres règles.</p>');
 if($('#project'))$('#project').onclick=()=>modal(`<span class="eyebrow">UN OBJECTIF POUR TOUS</span><h2 style="margin-top:14px">Notre guide de transmission</h2><p>Cette proposition fictive comporte cinq étapes de 20 %. Son avancement est indépendant des 48 cases.</p><ul>${['Identifier les besoins','Rédiger les procédures','Préparer les outils','Tester avec l’équipe','Valider et partager le guide'].map((x,i)=>`<li>${state.project[i]?'✓':'○'} ${x}</li>`).join('')}</ul><p>À 100 %, une célébration collective est acquise pour toute l’équipe, selon les modalités à définir.</p>`);
 document.querySelectorAll('[data-metric]').forEach(b=>b.oninput=()=>{state.values[+b.dataset.metric]=Math.min(+b.dataset.metric<3?100:100000,Math.max(0,Number(b.value)||0));$('#calc').textContent=fmt(score())+' % → +'+fmt(score()*.04)+' cases';save()});document.querySelectorAll('[data-project]').forEach(b=>b.onchange=()=>{state.project[+b.dataset.project]=b.checked;save();toast('Projet commun mis à jour : '+state.project.filter(Boolean).length*20+' %.')});if($('#message'))$('#message').oninput=e=>{state.message=e.target.value;save()};if($('#quality'))$('#quality').onchange=e=>{state.quality=e.target.checked;save()};if($('#publish'))$('#publish').onclick=()=>{if(!state.quality){toast('Validation en attente : terminez le contrôle humain.');return}if(state.month>=12)return;let before=state.position,s=score(),gain=s*.04;state.position=Math.min(48,before+gain);state.month++;state.lastScore=s;state.lastGain=gain;state.history.unshift(`Mois ${state.month} validé : ${fmt(s)} %, +${fmt(gain)} cases. Position ${fmt(state.position)}.`);save();page='parcours';render();let won=gifts.filter(g=>g.n>before&&g.n<=state.position);toast(won.length?'Un nouveau palier est acquis : '+won[0].title+' !':'Un nouveau pas ensemble : +'+fmt(gain)+' cases.');if(won.length)setTimeout(()=>gift(won[0]),600)};
}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#reset').onclick=()=>{modal('<h2>Reprendre la démonstration ?</h2><p>La simulation reviendra au mois 5, à la case 16,4. Vos essais locaux seront effacés.</p><button id="confirmreset" class="button">Recommencer</button>');$('#confirmreset').onclick=()=>{state=initial();save();page='parcours';$('#modal').close();render();toast('La démonstration est réinitialisée.')}};render();
